{
  "name": "gemini-api-proxy",
  "version": "1.0.0",
  "description": "Vercel-hosted GitHub-backed API proxy for Gemini text, image, video, embeddings, model listing, OpenAI-compatible paths, and tool-call-style outputs.",
  "main": "api/index.js",
  "scripts": {
    "test": "node test.js"
  },
  "dependencies": {
    "@google/genai": "^0.1.1"
  },
  "devDependencies": {}
}

const { GoogleGenAI } = require('@google/genai');

const apiKey = process.env.GEMINI_API_KEY || process.env.GOOGLE_API_KEY;
const ai = new GoogleGenAI({ apiKey });

module.exports = async (req, res) => {
  // Enable CORS
  res.setHeader('Access-Control-Allow-Credentials', true);
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET,OPTIONS,PATCH,DELETE,POST,PUT');
  res.setHeader(
    'Access-Control-Allow-Headers',
    'X-CSRF-Token, X-Requested-With, Accept, Accept-Version, Content-Length, Content-MD5, Content-Type, Date, X-Api-Version, Authorization'
  );

  if (req.method === 'OPTIONS') {
    res.status(200).end();
    return;
  }

  const urlPath = req.url.split('?')[0];
  const segments = urlPath.split('/').filter(Boolean);
  // e.g. /v1/chat/completions or /v1beta/models or /gemini/text

  try {
    // 1. Model Listing: GET /v1/models or /v1beta/models or /models
    if (req.method === 'GET' && (segments.includes('models') || segments.length === 0)) {
      try {
        const response = await ai.models.list();
        return res.status(200).json(response);
      } catch (e) {
        // Fallback static list if SDK call fails
        return res.status(200).json({
          object: 'list',
          data: [
            { id: 'gemini-2.5-flash', object: 'model', owned_by: 'google' },
            { id: 'gemini-2.5-pro', object: 'model', owned_by: 'google' },
            { id: 'gemini-1.5-flash', object: 'model', owned_by: 'google' },
            { id: 'gemini-1.5-pro', object: 'model', owned_by: 'google' }
          ]
        });
      }
    }

    // Parse body for POST requests
    let body = req.body;
    if (typeof body === 'string') {
      try { body = JSON.parse(body); } catch (e) { body = {}; }
    }
    body = body || {};

    // 2. OpenAI-compatible Chat Completions: /v1/chat/completions
    if (urlPath.includes('chat/completions') || urlPath.includes('openai')) {
      const modelName = body.model || 'gemini-2.5-flash';
      const messages = body.messages || [];

      // Convert OpenAI messages to Gemini contents format
      let contents = [];
      let systemInstruction = undefined;

      for (const msg of messages) {
        if (msg.role === 'system') {
          systemInstruction = msg.content;
        } else {
          contents.push({
            role: msg.role === 'assistant' ? 'model' : 'user',
            parts: [{ text: typeof msg.content === 'string' ? msg.content : JSON.stringify(msg.content) }]
          });
        }
      }

      const config = {};
      if (systemInstruction) {
        config.systemInstruction = systemInstruction;
      }
      if (body.temperature !== undefined) config.temperature = body.temperature;
      if (body.max_tokens !== undefined) config.maxOutputTokens = body.max_tokens;
      if (body.tools) {
        // Map OpenAI tools to Gemini function declarations if possible
        config.tools = body.tools.map(t => ({
          functionDeclarations: [t.function]
        }));
      }

      const response = await ai.models.generateContent({
        model: modelName.includes('gemini') ? modelName : 'gemini-2.5-flash',
        contents,
        config
      });

      // Format back to OpenAI response structure
      const text = response.text || '';
      const functionCalls = response.functionCalls ? response.functionCalls() : null;

      const messageObj = { role: 'assistant', content: text };
      if (functionCalls && functionCalls.length > 0) {
        messageObj.tool_calls = functionCalls.map((fc, idx) => ({
          id: 'call_' + idx,
          type: 'function',
          function: {
            name: fc.name,
            arguments: JSON.stringify(fc.args)
          }
        }));
        messageObj.content = null;
      }

      return res.status(200).json({
        id: 'chatcmpl-' + Date.now(),
        object: 'chat.completion',
        created: Math.floor(Date.now() / 1000),
        model: modelName,
        choices: [{
          index: 0,
          message: messageObj,
          finish_reason: 'stop'
        }],
        usage: {
          prompt_tokens: response.usageMetadata?.promptTokenCount || 0,
          completion_tokens: response.usageMetadata?.candidatesTokenCount || 0,
          total_tokens: response.usageMetadata?.totalTokenCount || 0
        }
      });
    }

    // 3. Embeddings: /v1/embeddings or /embeddings
    if (urlPath.includes('embeddings')) {
      const modelName = body.model || 'text-embedding-004';
      const input = body.input;
      const texts = Array.isArray(input) ? input : [input];

      const data = [];
      for (let i = 0; i < texts.length; i++) {
        const resEmbed = await ai.models.embedContent({
          model: modelName,
          contents: texts[i]
        });
        data.push({
          object: 'embedding',
          index: i,
          embedding: resEmbed.embedding?.values || []
        });
      }

      return res.status(200).json({
        object: 'list',
        data,
        model: modelName
      });
    }

    // 4. Native / Custom Gemini Endpoints (text, image, video, tools)
    const modelName = body.model || 'gemini-2.5-flash';
    const prompt = body.prompt || body.text || 'Hello';

    // Handle multimodal/image/video input if provided as inlineData or urls
    let contents = prompt;
    if (body.parts) {
      contents = body.parts;
    } else if (body.image || body.video) {
      contents = [
        prompt,
        {
          inlineData: {
            mimeType: body.imageType || 'image/jpeg',
            data: body.image || body.video
          }
        }
      ];
    }

    const config = {};
    if (body.systemInstruction) config.systemInstruction = body.systemInstruction;
    if (body.tools) config.tools = body.tools;
    if (body.temperature !== undefined) config.temperature = body.temperature;

    const response = await ai.models.generateContent({
      model: modelName,
      contents,
      config
    });

    return res.status(200).json({
      success: true,
      model: modelName,
      text: response.text,
      functionCalls: response.functionCalls ? response.functionCalls() : undefined,
      usage: response.usageMetadata
    });

  } catch (error) {
    console.error('API Proxy Error:', error);
    return res.status(500).json({
      error: { 
        message: error.message,
        stack: error.stack 
      }
    });
  }
};

const assert = require('assert');

async function runTests() {
  console.log('Running test suite for Gemini API Proxy...');

  // Test structure & syntax
  const handler = require('./api/index.js');
  assert(typeof handler === 'function', 'Handler should be a function');

  console.log('All local static structure checks passed successfully!');
}

runTests().catch(err => {
  console.error('Test failed:', err);
  process.exit(1);
});
